#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: PaperExplorer, Mac-only setup. Tower setup is a separate wizard.
# Run from anywhere: scripts/setup-mac.sh
# ──────────────────────────────────────────────────────────────────────────

cd "$(dirname "$0")/.."
TOTAL_STAGES=7
SEED_TITLE_QUERY="brain entropy psychedelic"

banner "PaperExplorer · Mac setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools on this Mac"
say "Checking for git, uv, gh (GitHub CLI) and docker."
missing=()
for tool in git uv gh docker; do
  if command -v "$tool" >/dev/null 2>&1; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$tool"
  else
    printf '  %s✗%s %s\n' "$RED" "$RESET" "$tool"; missing+=("$tool")
  fi
done
if (( ${#missing[@]} )); then
  say ""
  step "Install what's missing with Homebrew, e.g.:"
  note "  brew install gh uv        (docker: Docker Desktop or OrbStack)"
  pause "Press Enter once installed, or Ctrl-C and re-run later."
  for tool in "${missing[@]}"; do
    command -v "$tool" >/dev/null 2>&1 || { warn "$tool still missing; re-run when installed"; exit 1; }
  done
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sign in to GitHub"
if gh auth status >/dev/null 2>&1; then
  printf '  %s✓%s already signed in as %s\n' "$GREEN" "$RESET" "$(gh api user --jq .login)"
else
  say "gh will open a browser: choose GitHub.com, HTTPS, and 'Login with a web browser'."
  gh auth login --hostname github.com --git-protocol https --web
fi
gh auth setup-git
note "git now uses gh for GitHub credentials."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the GitHub repository and push"
if git remote get-url origin >/dev/null 2>&1; then
  printf '  %s✓%s remote origin already set: %s\n' "$GREEN" "$RESET" "$(git remote get-url origin)"
else
  ask GH_REPO "Repository name (e.g. PaperExplorer):"
  GH_REPO="${GH_REPO:-PaperExplorer}"
  visibility="--private"
  confirm "Make it public instead of private?" && visibility="--public"
  confirm "Create github.com/$(gh api user --jq .login)/$GH_REPO now?" || { warn "stopped before creating the repo"; exit 1; }
  gh repo create "$GH_REPO" "$visibility" --source=. --remote=origin \
    --description "Follow a paper's citations into the cited works' own words."
fi
say "Pushing main, dev and feat/repo-skeleton…"
git push -u origin main dev feat/repo-skeleton
gh repo edit --default-branch dev
printf '  %s✓%s default branch set to dev, so PRs target it by default\n' "$GREEN" "$RESET"
note "Optional: protect dev and main under Settings → Rules (rulesets on private repos need GitHub Pro)."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Local Python environment"
say "Installing Python 3.14 and all packages into .venv, then the pre-commit hooks."
uv sync
uv run pre-commit install
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Docker and the full test suite"
until docker info >/dev/null 2>&1; do
  warn "Docker isn't running."
  step "Start Docker Desktop or OrbStack and wait until it says it's running."
  pause "Press Enter to check again."
done
printf '  %s✓%s Docker is running\n' "$GREEN" "$RESET"
say "Running the gate: ruff, format check, pyright, pytest (first run pulls the pgvector image)."
uv run ruff check . && uv run ruff format --check . && uv run pyright
pytest_log=$(mktemp)
uv run pytest -q -rs | tee "$pytest_log"
if grep -qi "skipped" "$pytest_log"; then
  warn "some tests were skipped; the database tests should run when Docker is up"
  SKIPPED+=("store tests were skipped: check Docker, then run: uv run pytest -rs")
else
  printf '  %s✓%s all tests ran, including the real-Postgres ones\n' "$GREEN" "$RESET"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Zotero Web API key"
[[ -f "$ENV_FILE" ]] || { cp .env.example "$ENV_FILE"; note "created $ENV_FILE from .env.example"; }
open_url "https://www.zotero.org/settings/keys"
step "At the top, note the line 'Your userID for use in API calls is …'."
ask PE_ZOTERO_LIBRARY_ID "Paste that userID (digits only):"
step "Click 'Create new private key'. Name it 'PaperExplorer'."
step "Personal Library: tick 'Allow library access' AND 'Allow write access'."
step "Save Key, then copy the key shown (it's shown only once)."
ask_secret PE_ZOTERO_API_KEY "Paste the API key:"
write_env PE_ZOTERO_LIBRARY_ID "$PE_ZOTERO_LIBRARY_ID"
write_env PE_ZOTERO_LIBRARY_TYPE "user"
write_env PE_ZOTERO_API_KEY "$PE_ZOTERO_API_KEY"
say "Checking the key against the Zotero API…"
key_info=$(curl -fsS -H "Zotero-API-Key: $PE_ZOTERO_API_KEY" https://api.zotero.org/keys/current || true)
if [[ "$key_info" == *"\"userID\": $PE_ZOTERO_LIBRARY_ID"* || "$key_info" == *"\"userID\":$PE_ZOTERO_LIBRARY_ID"* ]]; then
  printf '  %s✓%s key belongs to user %s\n' "$GREEN" "$RESET" "$PE_ZOTERO_LIBRARY_ID"
  if printf '%s' "$key_info" | grep -Eq '"write": *true'; then
    printf '  %s✓%s write access granted\n' "$GREEN" "$RESET"
  else
    warn "no write access: edit the key and tick 'Allow write access' (the pipeline creates items)"
    SKIPPED+=("Zotero key needs write access")
  fi
else
  warn "the key didn't verify for user $PE_ZOTERO_LIBRARY_ID; re-run this wizard to re-enter it"
  SKIPPED+=("Zotero key verification failed")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Find the Seed paper and open the first PR"
say "Searching your Zotero library for: $SEED_TITLE_QUERY"
curl -fsS -G -H "Zotero-API-Key: $PE_ZOTERO_API_KEY" \
  --data-urlencode "q=$SEED_TITLE_QUERY" --data "limit=5" --data "format=json" \
  "https://api.zotero.org/users/$PE_ZOTERO_LIBRARY_ID/items/top" \
  | uv run python -c '
import json, sys
items = json.load(sys.stdin)
if not items:
    print("  no match: search for it in Zotero and note its item key")
for it in items:
    print("  " + it["key"] + "  " + it["data"].get("title", "?"))
' || warn "Zotero search failed"
note "Keep the Seed's item key: it starts the first Exploration (paperexplorer explore <key>)."
say ""
if gh pr view feat/repo-skeleton >/dev/null 2>&1; then
  printf '  %s✓%s PR already open: %s\n' "$GREEN" "$RESET" "$(gh pr view feat/repo-skeleton --json url --jq .url)"
elif confirm "Open the PR feat/repo-skeleton → dev now?"; then
  gh pr create --base dev --head feat/repo-skeleton --title "Repo skeleton" --body "$(cat <<'BODY'
First PR: the repo skeleton and design docs.

- uv workspace on Python 3.14 with `core`, `api`, `web` packages
- ruff, pyright strict, pytest, pre-commit; real Postgres in tests via testcontainers
- Settings, logging, CLI, SQL migration runner with pgvector
- API `/health` + typed client; web index showing API status
- `compose.yaml` and Dockerfiles for the tower (not yet built)
- Mac setup wizard (`scripts/setup-mac.sh`)

🤖 Generated with [Claude Code](https://claude.com/claude-code)

https://claude.ai/code/session_01DMEjtazZrEBrnH227DD7MR
BODY
)"
else
  SKIPPED+=("open the PR: gh pr create --base dev --head feat/repo-skeleton")
fi
SKIPPED+=("tower setup (Docker + GPU, Zotero desktop, compose up): separate wizard")
pause

finish
